python3 << 'EOF'
import zipfile
import re

z = zipfile.ZipFile('/root/project_proposal_ready.hwpx')

print("=== FINAL VERIFICATION ===\n")

for name in z.namelist():
    if name.endswith('.xml'):
        content = z.read(name).decode('utf-8')
        print(f"File: {name}")

        # Check for placeholders
        placeholders = re.findall(r'\{\{.*?\}\}', content)
        if placeholders:
            print(f"  ❌ FAIL: Remaining placeholders: {placeholders}")
        else:
            print(f"  ✅ No placeholders remaining")

        # Check budget format (should have no commas but keep currency symbol)
        if '예산' in content:
            budget_match = re.search(r'예산:\\s*([₩\\\\][\\d]+)', content)
            if budget_match:
                budget_val = budget_match.group(1)
                if ',' in budget_val:
                    print(f"  ❌ FAIL: Budget has commas: {budget_val}")
                else:
                    print(f"  ✅ Budget format correct: {budget_val}")
            else:
                budget_match2 = re.search(r'예산.*?(₩[\\d,]+)', content)
                if budget_match2:
                    val = budget_match2.group(1)
                    if ',' in val:
                        print(f"  ❌ Budget still has commas: {val}")
                    else:
                        print(f"  ✅ Budget value: {val}")

        # Check linesegarray in modified paragraphs
        # Modified paragraphs are those with specific content (not just headers)
        if 'hp:linesegarray' in content:
            # Count in paragraphs that should have been modified
            # These are okay if in unchanged paragraphs
            lineseg_count = content.count('<hp:linesegarray/>')
            print(f"  ℹ️  hp:linesegarray count: {lineseg_count}")

        # Check month spans in phase lines
        if '단계' in content:
            phase_lines = re.findall(r'<hp:t>.*단계.*</hp:t>', content)
            for line in phase_lines:
                if '개월' in line:
                    months = re.search(r'(\\d+)개월', line)
                    if months:
                        print(f"  ✅ Month span added: {months.group(1)}개월")
                else:
                    # Phase 3 is a single month, may not have month span
                    if '2027-01)' in line or '2027-01)' in line:
                        print(f"  ℹ️ Phase 3 (single month, no span needed)")

        print()

print("=== Output file location: /root/project_proposal_ready.hwpx ===")
EOF
